window.__finlexDocLoaded(10049,{"id":10049,"articles":[{"id":1000128,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Standalone global auditing standard designed specifically for audits of financial statements of less complex entities (LCEs), providing a proportionate risk-based audit framework effective for periods beginning on or after 15 Dec 2025.","seq":0},{"id":1000129,"no":"ISA for LCE Parts 1–10","heading":"Proportionate Standalone Audit Standard for Less Complex Entities","text":"Effective for periods beginning on or after 15 Dec 2025; prohibits use for listed entities, public interest entities (PIEs), or complex groups; delivers the same 'reasonable assurance' level as full ISAs through streamlined, self-contained risk-based requirements.","seq":1},{"id":1000130,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 3 (ISA for LCE)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
